import React, { useState, useEffect } from 'react';
import { AuthProvider, useAuth } from './context/AuthContext';
import { projects as projectsApi } from './api';
import TaskBoard from './components/TaskBoard';

// ─── Auth Page ───────────────────────────────────────────────────────────────
function AuthPage() {
  const { login, register } = useAuth();
  const [mode, setMode] = useState('login');
  const [form, setForm] = useState({ username: '', email: '', password: '', password2: '', first_name: '', last_name: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handle = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      mode === 'login' ? await login(form) : await register(form);
    } catch (err) {
      setError(err.message || 'Authentication failed. Please check your credentials.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ minHeight: '100vh', background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }}>
      <div style={{ background: '#fff', borderRadius: 16, padding: 36, width: '100%', maxWidth: 400, boxShadow: '0 20px 60px rgba(0,0,0,0.2)' }}>
        <div style={{ textAlign: 'center', marginBottom: 28 }}>
          <div style={{ fontSize: 36 }}>⚡</div>
          <h1 style={{ margin: 0, fontSize: 26, color: '#1a1a2e' }}>TaskFlow</h1>
        </div>

        <div style={{ display: 'flex', borderRadius: 8, background: '#f0f0f0', padding: 3, marginBottom: 20 }}>
          {['login', 'register'].map(m => (
            <button key={m} onClick={() => { setMode(m); setError(''); }} style={{ flex: 1, padding: '8px 0', border: 'none', borderRadius: 6, cursor: 'pointer', background: mode === m ? '#fff' : 'transparent', color: mode === m ? '#1a1a2e' : '#888', transition: 'all 0.2s' }}>
              {m === 'login' ? 'Sign In' : 'Register'}
            </button>
          ))}
        </div>

        {error && <div style={{ background: '#fff5f5', color: '#dc3545', padding: '10px', borderRadius: 8, marginBottom: 14, fontSize: 13 }}>{error}</div>}

        <form onSubmit={handle}>
          {mode === 'register' && (
            <div style={{ display: 'flex', gap: 10 }}>
              <input placeholder="First name" value={form.first_name} onChange={e => setForm({...form, first_name: e.target.value})} style={authInput} />
              <input placeholder="Last name" value={form.last_name} onChange={e => setForm({...form, last_name: e.target.value})} style={authInput} />
            </div>
          )}
          <input required placeholder="Username" value={form.username} onChange={e => setForm({...form, username: e.target.value})} style={authInput} />
          {mode === 'register' && <input type="email" required placeholder="Email" value={form.email} onChange={e => setForm({...form, email: e.target.value})} style={authInput} />}
          <input required type="password" placeholder="Password" value={form.password} onChange={e => setForm({...form, password: e.target.value})} style={authInput} />
          {mode === 'register' && <input required type="password" placeholder="Confirm password" value={form.password2} onChange={e => setForm({...form, password2: e.target.value})} style={authInput} />}

          <button type="submit" disabled={loading} style={{ ...authBtn, opacity: loading ? 0.7 : 1 }}>
            {loading ? 'Please wait...' : (mode === 'login' ? 'Sign In' : 'Create Account')}
          </button>
        </form>
      </div>
    </div>
  );
}

// ─── Dashboard ────────────────────────────────────────────────────────────────
function Dashboard() {
  const { user, logout } = useAuth();
  const [projectList, setProjectList] = useState([]);
  const [activeProject, setActiveProject] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    projectsApi.list()
      .then(data => { setProjectList(data); setLoading(false); })
      .catch(() => setLoading(false));
  }, []);

  return (
    <div style={{ minHeight: '100vh', background: '#f4f6fb' }}>
      <nav style={{ background: '#fff', padding: '15px 24px', display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #e9ecef' }}>
        <span style={{ fontWeight: 800 }}>TaskFlow</span>
        <div>
          <span style={{ marginRight: 15, fontSize: 13 }}>{user?.username}</span>
          <button onClick={logout} style={{ padding: '4px 8px', cursor: 'pointer' }}>Sign Out</button>
        </div>
      </nav>
      <div style={{ display: 'flex' }}>
        <aside style={{ width: 260, padding: 20 }}>
          {loading ? <p>Loading projects...</p> : projectList.map(p => (
            <div key={p.id} onClick={() => setActiveProject(p)} style={{ padding: 10, cursor: 'pointer', background: activeProject?.id === p.id ? '#e0e7ff' : 'white', marginBottom: 5, borderRadius: 6 }}>
              {p.name}
            </div>
          ))}
        </aside>
        <main style={{ flex: 1, padding: 20 }}>
          {activeProject ? <TaskBoard projectId={activeProject.id} /> : <p>Select a project to view tasks.</p>}
        </main>
      </div>
    </div>
  );
}

// ─── Root App ─────────────────────────────────────────────────────────────────
export default function App() {
  return (
    <AuthProvider>
      <AppWrapper />
    </AuthProvider>
  );
}

function AppWrapper() {
  const { user, loading } = useAuth();
  if (loading) return <div style={{ height: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>Loading...</div>;
  return user ? <Dashboard /> : <AuthPage />;
}

// Styles
const authInput = { width: '100%', padding: 10, marginBottom: 10, border: '1px solid #ccc', borderRadius: 8, boxSizing: 'border-box' };
const authBtn = { width: '100%', padding: 12, background: '#667eea', color: '#fff', border: 'none', borderRadius: 8, cursor: 'pointer' };
